package com.mavric.healthsqlserver;

import java.util.*;
import com.microsoft.sqlserver.jdbc.SQLServerDataSource;
import com.zaxxer.hikari.HikariDataSource;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import org.springframework.beans.factory.support.*;
import static com.mavric.healthsqlserver.SqlServerRuntimeRootTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class SqlServerRuntimeModeGuardTest {
    static final String CANARY="private-password-canary";
    static void safe(Throwable failure){var seen=Collections.newSetFromMap(new IdentityHashMap<Throwable,Boolean>());boolean found=false;while(failure!=null && seen.add(failure)){assertFalse(Objects.toString(failure.getMessage(),"").contains(CANARY));if("Unsafe SQL Server runtime configuration.".equals(failure.getMessage())){found=true;assertNull(failure.getCause());}failure=failure.getCause();}assertTrue(found);}
    static void rejected(Map<String,String> properties){try(var pools=mockConstruction(HikariDataSource.class);var drivers=mockConstruction(SQLServerDataSource.class);var context=context(properties)){safe(assertThrows(RuntimeException.class,context::refresh));assertTrue(pools.constructed().isEmpty());assertTrue(drivers.constructed().isEmpty());}}
    @Test void everyRequiredModeAndBooleanMissingOrInvalidStopsBeforeDataSources(){for(String key:List.of("health.sqlserver.mode","spring.flyway.enabled","spring.sql.init.mode","management.endpoint.health.probes.enabled")){var missing=valid();missing.remove(key);rejected(missing);for(String invalid:List.of("",CANARY,"true","false")){if(invalid.equals(valid().get(key)))continue;var properties=valid();properties.put(key,invalid);rejected(properties);}}}
    @Test void setupFlagsAreForbiddenByPresenceEvenEmptyOrFalse(){for(String key:List.of("migrate","setup","bootstrap"))for(String value:List.of("","false",CANARY)){var properties=valid();properties.put(key,value);rejected(properties);}}
    @Test void credentialsJobsOverrideAndSensitiveHealthExposureAreRejectedWithoutValues(){for(String key:List.of("MIGRATION_USER","MIGRATION_PASSWORD","spring.flyway.url","spring.flyway.user","spring.flyway.password","BOOTSTRAP_ADMIN_EMAIL","BOOTSTRAP_ADMIN_PASSWORD","health.bootstrap.email","health.bootstrap.password")){var properties=valid();properties.put(key,CANARY);rejected(properties);}for(String key:List.of("health.sqlserver.jobs.enabled","spring.main.allow-bean-definition-overriding","management.endpoint.health.show-details","management.endpoint.health.show-components"))for(String value:List.of("true","always","when-authorized",CANARY)){var properties=valid();properties.put(key,value);rejected(properties);}}
    @Test void healthGroupsMustBeExplicitExactAndWithoutDuplicatesOrWildcards(){for(String key:List.of("management.endpoint.health.group.liveness.include","management.endpoint.health.group.readiness.include")){var missing=valid();missing.remove(key);rejected(missing);for(String value:List.of("","*","db","readinessState,db,db","livenessState,db",CANARY)){if(value.equals(valid().get(key)))continue;var properties=valid();properties.put(key,value);rejected(properties);}}}
    @Test void validOrderIndependentAndIndexedGroupsDisableOverrideLocallyWithoutChangingEnvironment(){var properties=valid();properties.put("management.endpoint.health.group.readiness.include","db,readinessState");properties.put("spring.main.allow-bean-definition-overriding","false");properties.put("health.sqlserver.jobs.enabled","false");properties.put("management.endpoint.health.show-details","never");properties.put("management.endpoint.health.show-components","never");for(String key:List.of("MIGRATION_USER","MIGRATION_PASSWORD","spring.flyway.url","spring.flyway.user","spring.flyway.password","BOOTSTRAP_ADMIN_EMAIL","BOOTSTRAP_ADMIN_PASSWORD","health.bootstrap.email","health.bootstrap.password"))properties.put(key,"");for(boolean indexed:List.of(false,true)){var env=new MockEnvironment();var copy=new LinkedHashMap<>(properties);if(indexed){copy.remove("management.endpoint.health.group.readiness.include");copy.put("management.endpoint.health.group.readiness.include[0]","readinessState");copy.put("management.endpoint.health.group.readiness.include[1]","db");}copy.forEach(env::withProperty);var factory=new DefaultListableBeanFactory();factory.setAllowBeanDefinitionOverriding(true);var guard=new SqlServerRuntimeModeGuard(env);assertDoesNotThrow(()->guard.postProcessBeanDefinitionRegistry(factory));guard.postProcessBeanFactory(factory);assertFalse(factory.isAllowBeanDefinitionOverriding());assertEquals("runtime",env.getProperty("health.sqlserver.mode"));assertNull(env.getProperty("health.sqlserver.jobs.other"));factory.registerBeanDefinition("synthetic",new RootBeanDefinition(Object.class));assertThrows(BeanDefinitionOverrideException.class,()->factory.registerBeanDefinition("synthetic",new RootBeanDefinition(String.class)));}}
}
